policies.inbound:






    {{apim-app-client-id}}
    api://{{apim-app-client-id}}











  https://login.microsoftonline.com/{{tenant-id}}/oauth2/v2.0/token
  POST

    application/x-www-form-urlencoded

  @{
    var userToken       = (string)context.Variables["UserToken"];
    var miToken         = (string)context.Variables["MiAssertionToken"];
    var clientId        = "{{apim-app-client-id}}";
    var adoScope        = "{{ado-scope}} offline_access";
    return
      "grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer"
      + "&client_id="            + Uri.EscapeDataString(clientId)
      + "&client_assertion_type=urn:ietf:params:oauth:client-assertion-type:jwt-bearer"
      + "&client_assertion="     + Uri.EscapeDataString(miToken)
      + "&assertion="            + Uri.EscapeDataString(userToken)
      + "&scope="                + Uri.EscapeDataString(adoScope)
      + "&requested_token_use=on_behalf_of";
  }




  <when condition="@{
    var status = ((IResponse)context.Variables["OboResponse"]).StatusCode;
    if (status != 200) {
      var body = ((IResponse)context.Variables["OboResponse"]).Body.As(preserveContent: true);
      return body.Contains("interaction_required")
          || body.Contains("consent_required")
          || body.Contains("invalid_grant");
    }
    return false;
  }">




        application/json

      @{
        var gatewayUrl = context.Request.OriginalUrl.Scheme + "://" + context.Request.OriginalUrl.Host;
        var oboBody    = ((IResponse)context.Variables["OboResponse"]).Body.As(preserveContent: true);
        return Newtonsoft.Json.JsonConvert.SerializeObject(new {
          error       = "consent_required",
          description = "Admin consent is required to access Azure DevOps. An admin must visit consent_uri to grant access for the organization.",
          consent_uri = gatewayUrl + "/authorize",
          obo_error   = oboBody
        });
      }







        application/json

      @{
        var body = ((IResponse)context.Variables["OboResponse"]).Body.As(preserveContent: true);
        return Newtonsoft.Json.JsonConvert.SerializeObject(new {
          error       = "obo_exchange_failed",
          description = "The OBO token exchange failed.",
          details     = body
        });
      }





<set-variable name="AdoAccessToken"
              value="@(((IResponse)context.Variables["OboResponse"]).Body.As()["access_token"].ToString())" />


  @("Bearer " + (string)context.Variables["AdoAccessToken"])

set-header.value:
@{
            var gatewayUrl = context.Request.OriginalUrl.Scheme + "://" + context.Request.OriginalUrl.Host;
            return "Bearer resource_metadata=\"" + gatewayUrl + "/well-known/oauth-protected-resource\"";
          }
